package com.InnovaServe.core.repository;import com.InnovaServe.core.entity.AuditLog;import org.springframework.data.jpa.repository.*;import org.springframework.data.repository.query.Param;import java.time.LocalDateTime;import java.util.*;
public interface AuditLogRepository extends JpaRepository<AuditLog,UUID>{@Query("select a from AuditLog a where a.tenantId=:t and (:type is null or a.entityType=:type) and (:entity is null or a.entityId=:entity) and (:user is null or a.userId=:user) and (:from is null or a.createdAt>=:from) and (:to is null or a.createdAt<=:to) order by a.createdAt desc")List<AuditLog> search(@Param("t")UUID tenant,@Param("type")String type,@Param("entity")UUID entity,@Param("user")UUID user,@Param("from")LocalDateTime from,@Param("to")LocalDateTime to);}
